import "../../styles/teum-base.css";
import "../../styles/components/badge.css";
import { X } from "@phosphor-icons/react";
import type { ComponentPropsWithRef, ReactNode } from "react";
import { cn } from "../../lib/cn";

export type BadgeProps = ComponentPropsWithRef<"span"> & {
  variant?: "neutral" | "strong" | "outline" | "success" | "warning" | "danger";
  leadingIcon?: ReactNode;
  removable?: boolean;
  onRemove?: () => void;
  removeLabel?: string;
};

export function Badge({
  className,
  variant = "neutral",
  leadingIcon,
  removable,
  onRemove,
  removeLabel = "Remove",
  children,
  ...props
}: BadgeProps) {
  return (
    <span className={cn("teum-badge", `teum-badge--${variant}`, className)} {...props}>
      {leadingIcon && <span className="teum-badge__icon" aria-hidden="true">{leadingIcon}</span>}
      <span className="teum-badge__label">{children}</span>
      {removable && (
        <button type="button" className="teum-badge__remove" aria-label={removeLabel} onClick={onRemove}>
          <X aria-hidden="true" />
        </button>
      )}
    </span>
  );
}

/* Generated from src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-badge {
  display: inline-flex;
  min-width: 0;
  height: 21px;
  align-items: center;
  gap: 4px;
  padding: 0 6px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: color-mix(in oklch, var(--teum-bg-subtle) 88%, transparent);
  color: var(--teum-fg-muted);
  font-size: 11.5px;
  font-weight: 550;
  line-height: 1;
  letter-spacing: -0.006em;
  white-space: nowrap;
}

.teum-badge__icon,
.teum-badge__icon svg { width: 11px; height: 11px; flex: 0 0 auto; }

.teum-badge__label { overflow: hidden; text-overflow: ellipsis; }

.teum-badge__remove {
  display: grid;
  width: 17px;
  height: 17px;
  margin-right: -4px;
  place-items: center;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: currentColor;
  cursor: pointer;
}

.teum-badge__remove svg { width: 11px; height: 11px; }

.teum-badge__remove:focus-visible { outline: 1.5px solid currentColor; outline-offset: -2px; }

@media (hover: hover) and (pointer: fine) {
.teum-badge__remove:hover { background: var(--teum-hover); color: var(--teum-ink); }
}

.teum-badge__remove { transition: color var(--teum-hover-duration), background-color var(--teum-hover-duration), transform var(--teum-press-duration) var(--teum-ease-out); }

.teum-badge__remove:active { transform: scale(.96); }

@media (prefers-reduced-motion: reduce) {
.teum-badge__remove:active { transform: none; }
}
}
